nextflow_process {

    name "Test Process MINIA"
    script "../main.nf"
    process "MINIA"

    tag "modules"
    tag "modules_nfcore"
    tag "minia"

    test("sarscov2 - fastq - se") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
				    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_interleaved.fastq.gz', checkIfExists: true),                    ]
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.contigs[0][1]).linesGzip.any { it.contains('AAA') } },
                { assert path(process.out.unitigs[0][1]).linesGzip.any { it.contains('CCC') } },
                { assert snapshot(
                    file(process.out.contigs[0][1]).name,
                    file(process.out.unitigs[0][1]).name,
                    file(process.out.h5[0][1]).name,
                    file(process.out.log[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }
    }

    test("sarscov2 - fastq - pe") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
				    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
				        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.contigs[0][1]).linesGzip.any { it.contains('AAA') } },
                { assert path(process.out.unitigs[0][1]).linesGzip.any { it.contains('CCC') } },
                { assert snapshot(
                    file(process.out.contigs[0][1]).name,
                    file(process.out.unitigs[0][1]).name,
                    file(process.out.h5[0][1]).name,
                    file(process.out.log[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    ).match()
                }
            )
        }
    }

    test("test-minia-stub") {
        options '-stub'

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
				    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
				        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

}
